		if (conns.some((c) => c.type === item.type && c.x === item.x && c.y === item.y)) return toast("There is already a connection in that space.");
		update((p) => ({
			...p,
			connections: [...p.connections || [], item]
		}));
		onSelect({
			kind: "connection",
			id: item.id
		});
